reference_solution:
def three_sum_smaller(nums, target):
    ordered = sorted(nums)
    count = 0
    for left in range(len(ordered) - 2):
        middle, right = left + 1, len(ordered) - 1
        while middle < right:
            if ordered[left] + ordered[middle] + ordered[right] < target:
                count += right - middle
                middle += 1
            else:
                right -= 1
    return count

